using System.IO;
using System.Linq;
using ProjectTower.config;
using ProjectTower.player;

namespace SkillTreeEdit.skilltree;

public class SkillTree
{
	public static SkillImg[] imgs;

	public static SkillNode[] nodes;

	public static SkillNode[] enhancedNodes;

	public static SkillNode[] classicNodes;

	public static void Init()
	{
		ReadTree();
	}

	public static void ReadTree()
	{
		BinaryReader binaryReader = new BinaryReader(File.Open("skilltree/data/classic/skilltree.zsx", FileMode.Open, FileAccess.Read));
		Read(binaryReader);
		binaryReader.Close();
		BinaryReader binaryReader2 = new BinaryReader(File.Open("skilltree/data/enhanced/skilltree.zsx", FileMode.Open, FileAccess.Read));
		Read(binaryReader2, isEnhanced: true);
		binaryReader2.Close();
	}

	internal static void Read(BinaryReader reader, bool isEnhanced = false)
	{
		int num = reader.ReadInt32();
		nodes = new SkillNode[num];
		if (isEnhanced)
		{
			enhancedNodes = new SkillNode[num];
		}
		else
		{
			classicNodes = new SkillNode[num];
		}
		for (int i = 0; i < num; i++)
		{
			if (isEnhanced)
			{
				nodes[i] = (enhancedNodes[i] = new SkillNode(reader, i));
			}
			else
			{
				nodes[i] = (classicNodes[i] = new SkillNode(reader, i));
			}
		}
		if (!isEnhanced)
		{
			num = reader.ReadInt32();
			imgs = new SkillImg[num];
			for (int j = 0; j < num; j++)
			{
				imgs[j] = new SkillImg(reader);
			}
		}
	}

	public static bool GetCanUnlock(SkillNode node, PlayerStats pStats, bool hasUnlocks)
	{
		int num = 16;
		bool flag = false;
		if (pStats.classUnlocks[0] == -1 && pStats.classUnlocks[1] == -1 && node.ID == num && !hasUnlocks)
		{
			flag = true;
		}
		else if (pStats.classUnlocks[0] != node.ID && pStats.classUnlocks[1] != node.ID && pStats.treeUnlocks[node.ID] > 0)
		{
			flag = true;
		}
		else
		{
			for (int i = 0; i < 2; i++)
			{
				if (node.parent[i] > -1 && (pStats.treeUnlocks[node.parent[i]] > 0 || pStats.classUnlocks[0] == node.parent[i] || pStats.classUnlocks[1] == node.parent[i]))
				{
					flag = true;
				}
			}
			if (!flag)
			{
				for (int j = 0; j < nodes.Length; j++)
				{
					if (pStats.treeUnlocks[j] <= 0 && pStats.classUnlocks[0] != j && pStats.classUnlocks[1] != j)
					{
						continue;
					}
					for (int k = 0; k < 2; k++)
					{
						if (nodes[j].parent[k] == node.ID)
						{
							flag = true;
							break;
						}
					}
					if (flag)
					{
						break;
					}
				}
			}
			if (flag)
			{
				int type = node.type;
				if ((uint)type <= 16u || (uint)(type - 25) <= 3u)
				{
					if (GameModeMgr.IsGameEnhanced())
					{
						bool num2 = node.value == 3 && pStats.itemClass[node.type] == 4;
						bool flag2 = node.value == 2 && node.title[0].Contains('4') && pStats.itemClass[node.type] == 3;
						bool flag3 = node.value == 2 && node.title[0].Contains('3') && pStats.itemClass[node.type] == 2;
						bool flag4 = node.value == 1 && node.title[0].Contains('2') && pStats.itemClass[node.type] == 1;
						bool flag5 = node.value == 1 && node.title[0].Contains('1') && pStats.itemClass[node.type] == 0;
						if (!(num2 | flag2 | flag3 | flag4 | flag5))
						{
							flag = false;
						}
					}
					else if (pStats.itemClass[node.type] < node.value - 1)
					{
						flag = false;
					}
				}
			}
		}
		return flag;
	}
}

using System.IO;
using System.Text;
using LootEdit;
using Microsoft.Xna.Framework;
using ProjectTower;

namespace SkillTreeEdit.skilltree;

public class SkillNode
{
	public string name;

	public string[] title;

	public string[] desc;

	public string[] baseDesc;

	public int ID;

	public StringBuilder titleStr;

	public StringBuilder[] descStr;

	public StringBuilder[] baseDescStr;

	public const int TYPE_SWORD_CLASS = 0;

	public const int TYPE_AXE_CLASS_DEP = 1;

	public const int TYPE_MACE_CLASS = 2;

	public const int TYPE_DAGGER_CLASS = 3;

	public const int TYPE_SPEAR_CLASS_DEP = 4;

	public const int TYPE_SHIELD_CLASS = 5;

	public const int TYPE_GREATSWORD_CLASS_DEP = 6;

	public const int TYPE_GREATAXE_CLASS_DEP = 7;

	public const int TYPE_GREATHAMMER_CLASS = 8;

	public const int TYPE_WHIP_CLASS = 9;

	public const int TYPE_STAFF_CLASS = 10;

	public const int TYPE_BOW_CLASS = 11;

	public const int TYPE_CROSSBOW_CLASS = 12;

	public const int TYPE_PISTOL_CLASS_DEP = 13;

	public const int TYPE_POLEAXE_CLASS = 14;

	public const int TYPE_HALBERD_CLASS_DEP = 15;

	public const int TYPE_ARMOR_CLASS = 16;

	public const int TYPE_STR = 17;

	public const int TYPE_DEX = 18;

	public const int TYPE_MAG = 19;

	public const int TYPE_WIS = 20;

	public const int TYPE_END = 21;

	public const int TYPE_WILL = 22;

	public const int TYPE_HEALTH_POT = 23;

	public const int TYPE_MANA_POT = 24;

	public const int TYPE_PRAYER_CLASS = 25;

	public const int TYPE_MAGIC_CLASS = 26;

	public const int TYPE_WAND_CLASS = 27;

	public const int TYPE_LIGHT_ARMOR_CLASS = 28;

	public const int TOTAL_CLASSES = 29;

	private const int MAX_UPGRADES_PER_STAT_NODE = 5;

	public int type;

	public int value;

	public int cost;

	public int[] parent;

	public int img;

	public Vector2 loc;

	public int max;

	public const int MAX_PARENTS = 2;

	public SkillNode(int ID)
	{
		name = "new_node";
		title = new string[13];
		desc = new string[13];
		baseDesc = new string[13];
		for (int i = 0; i < title.Length; i++)
		{
			title[i] = "";
		}
		for (int j = 0; j < desc.Length; j++)
		{
			desc[j] = "";
		}
		for (int k = 0; k < baseDesc.Length; k++)
		{
			baseDesc[k] = "";
		}
		title[0] = "New Skill";
		desc[0] = "New Description";
		baseDesc[0] = "";
		cost = 1;
		this.ID = ID;
		parent = new int[2];
		for (int l = 0; l < 2; l++)
		{
			parent[l] = -1;
		}
	}

	public SkillNode(BinaryReader reader, int ID)
	{
		name = reader.ReadString();
		title = new string[13];
		desc = new string[13];
		baseDesc = new string[13];
		for (int i = 0; i < 13; i++)
		{
			title[i] = reader.ReadString();
		}
		this.ID = ID;
		titleStr = new StringBuilder(title[Game1.language]);
		for (int j = 0; j < 13; j++)
		{
			desc[j] = reader.ReadString();
		}
		for (int k = 0; k < 13; k++)
		{
			baseDesc[k] = reader.ReadString();
		}
		type = reader.ReadInt32();
		value = reader.ReadInt32();
		cost = reader.ReadInt32();
		parent = new int[2];
		for (int l = 0; l < 2; l++)
		{
			parent[l] = reader.ReadInt32();
		}
		loc = new Vector2(reader.ReadSingle(), reader.ReadSingle());
		img = reader.ReadInt32();
		max = GetMaxTreeUnlock();
	}

	internal int GetMaxTreeUnlock()
	{
		if (cost > 1)
		{
			return 1;
		}
		int num = type;
		if ((uint)(num - 17) <= 5u)
		{
			return 5;
		}
		return 1;
	}

	internal void CopyFrom(SkillNode other)
	{
		name = other.name;
		title = new string[other.title.Length];
		desc = new string[other.desc.Length];
		baseDesc = new string[other.baseDesc.Length];
		for (int i = 0; i < title.Length; i++)
		{
			title[i] = other.title[i];
		}
		for (int j = 0; j < desc.Length; j++)
		{
			desc[j] = other.desc[j];
		}
		for (int k = 0; k < baseDesc.Length; k++)
		{
			baseDesc[k] = other.baseDesc[k];
		}
		type = other.type;
		value = other.value;
		cost = other.cost;
		for (int l = 0; l < 2; l++)
		{
			parent[l] = other.parent[l];
		}
		loc = other.loc;
		img = other.img;
	}

	internal void Write(BinaryWriter writer)
	{
		writer.Write(name);
		for (int i = 0; i < 13; i++)
		{
			if (i < title.Length)
			{
				writer.Write(title[i]);
			}
			else
			{
				writer.Write(title[0] + " - " + TranslationMgr.GetLangStrFromIdx(i));
			}
		}
		for (int j = 0; j < 13; j++)
		{
			if (j < desc.Length)
			{
				writer.Write(desc[j]);
			}
			else
			{
				writer.Write("Untranslated Description: " + TranslationMgr.GetLangStrFromIdx(j));
			}
		}
		for (int k = 0; k < 13; k++)
		{
			if (k < baseDesc.Length)
			{
				writer.Write(baseDesc[k]);
			}
			else
			{
				writer.Write("Untranslated Base Description: " + TranslationMgr.GetLangStrFromIdx(k));
			}
		}
		writer.Write(type);
		writer.Write(value);
		writer.Write(cost);
		for (int l = 0; l < 2; l++)
		{
			writer.Write(parent[l]);
		}
		writer.Write(loc.X);
		writer.Write(loc.Y);
		writer.Write(img);
	}

	internal string ReplaceTextWithVal(string text, int value)
	{
		string newValue = value.ToString();
		return text.Replace("[v]", newValue);
	}
}
