	public bool UseBlackPearl(int count)
	{
		for (int i = 0; i < inventory.Length; i++)
		{
			if (inventory[i] == null || inventory[i].category != 7)
			{
				continue;
			}
			LootDef lootDef = LootCatalog.category[7].loot[inventory[i].catalogIdx];
			if (lootDef.type != 7 && lootDef.flags == 14 && inventory[i].count >= count)
			{
				inventory[i].count -= count;
				if (inventory[i].count <= 0)
				{
					inventory[i] = null;
				}
				return true;
			}
		}
		return false;
	}

