import json, collections, heapq
d=json.load(open('skilltree.json',encoding='utf-8'))
TN={0:'sword',2:'mace',3:'dagger',5:'shield',8:'greathammer',9:'whip',10:'staff',11:'bow',12:'crossbow',14:'pike',16:'hvyarmor',17:'STR',18:'DEX',19:'MAG',20:'WIS',21:'END',22:'WILL',23:'heal',24:'mana',25:'cleric',26:'magic',27:'wand',28:'lightarmor'}
STAT={17:'STR',18:'DEX',19:'MAG',20:'WIS',21:'END',22:'WILL'}
SC={'knight':[0,50],'mage':[42,262],'paladin':[3,50],'thief':[4],'chef':[],'cleric':[6,36],'pauper':[],'hunter':[8,13]}
def build(m):
    N=d[m]; vis={n['id'] for n in N if n['img']>=0}
    adj=collections.defaultdict(set)
    for n in N:
        for p in n['parent']:
            if p>=0 and n['id'] in vis and p in vis: adj[n['id']].add(p); adj[p].add(n['id'])
    return N,vis,adj
def sp(N,adj,owned,vis):
    # dijkstra over node-cost from owned set; returns dist (cost to add node incl. its cost), prev
    dist={}; prev={}
    pq=[]
    for o in owned:
        dist[o]=0; heapq.heappush(pq,(0,o))
    while pq:
        c,a=heapq.heappop(pq)
        if c>dist.get(a,1e9): continue
        for b in adj[a]:
            if b in owned: continue
            nc=c+N[b]['cost']
            if nc<dist.get(b,1e9): dist[b]=nc; prev[b]=a; heapq.heappush(pq,(nc,b))
    return dist,prev
def addpath(N,adj,owned,target,vis):
    dist,prev=sp(N,adj,owned,vis)
    path=[]; x=target
    while x not in owned:
        path.append(x); x=prev[x]
    for x in path: owned.add(x)
    return path
for m in ('classic','enhanced'):
    N,vis,adj=build(m)
    bt=collections.defaultdict(list)
    for n in N:
        if n['id'] in vis and n['type'] in TN and n['type']<17 or (n['id'] in vis and n['type'] in (25,26,27,28)): bt[n['type']].append(n)
    print('=====',m)
    for cls,marks in SC.items():
        owned=set(); free=set(marks)
        if not marks: owned.add(16); 
        owned|=free
        # cost of reaching each branch's rank1, and full chain greedily (from this start only, each branch independently)
        res={}
        for t,L in bt.items():
            L=sorted(L,key=lambda n:(n['value'],n['id']))
            o=set(owned); cost=0; stats=collections.Counter(); first=None; tax=0
            paid_branch=0
            for n in L:
                if n['id'] in o: continue
                p=addpath(N,adj,o,n['id'],vis)
                for x in p:
                    nn=N[x]
                    cost+=nn['cost']
                    if x==n['id'] or nn['type']==t: paid_branch+=nn['cost']
                    else:
                        tax+=nn['cost']
                        if nn['type'] in STAT: stats[STAT[nn['type']]]+=1
                if first is None: first=cost
            res[TN[t]]=(first,cost,tax,paid_branch,dict(stats))
        print(cls,'(marks',marks,') {branch: (cost_to_rank1, total_to_rank5, pure_tax_nodes, branch_cost, stat_gained_on_path)}')
        for k,v in sorted(res.items(),key=lambda kv:kv[1][1]):
            print('   ',k,v)
